app.js.beforeText:
(() => {
  const { theories, relations, trees, sources } = window.QI_DATA;
  const formulas = window.QI_FORMULAS?.formulas || [];
  const formulaAudit = window.QI_FORMULA_AUDIT?.entries || [];
  const developments = window.QI_DEVELOPMENTS?.events || [];
  const developmentTypes = window.QI_DEVELOPMENTS?.eventTypes || [];
  const questions = window.QI_QUESTIONS?.questions || [];
  const questionDispositions = window.QI_QUESTIONS?.dispositions || [];
  const problems = window.QI_PROBLEMS?.problems || [];
  const evidenceRecords = window.QI_EVIDENCE?.records || [];
  const passports = window.QI_PASSPORTS?.records || [];
  const passportByTheory = new Map(passports.map(passport=>[passport.theoryId,passport]));
  const problemById = new Map(problems.map(problem=>[problem.id,problem]));
  let selectedProblemId = problems[0]?.id || "";
  const formulaAuditByTheory = new Map(formulaAudit.map(x => [x.theoryId,x]));
  const byId = new Map(theories.map(t => [t.id,t]));
  const sourceById = new Map(sources.map(s => [s.id,s]));
  const profiles = window.QI_PROFILES?.profiles || {};
  let compareIds = [];
  let learningPathId = "";
  let workspaceSearch = "";
  const noteDrafts=new Map();
  try{for(const [id,draft] of Object.entries(JSON.parse(sessionStorage.getItem('quantum-index-drafts-v1')||'{}')))if(byId.has(id)&&typeof draft?.text==='string'&&typeof draft?.base==='string')noteDrafts.set(id,draft);}catch{}
  function persistDrafts(){try{sessionStorage.setItem('quantum-index-drafts-v1',JSON.stringify(Object.fromEntries(noteDrafts)));return true;}catch{return false;}}
  window.addEventListener('beforeunload',event=>{if(noteDrafts.size){event.preventDefault();event.returnValue='';}});
  window.addEventListener('storage',event=>{if(event.key!=='quantum-index-workspace-v1')return;window.QI_WORKSPACE.refresh();if(state.view==='workspace')renderWorkspace();if(state.view==='learn')renderLearningPaths();if(state.view==='theory'&&$('#researchStatus')){$('#researchStatus').textContent=window.QI_WORKSPACE.error||'Saved research changed in another tab. Your draft is retained; saving checks for conflicts.';}});
  const learningPaths = window.QI_PROFILES?.learningPaths || [];
  const profileFields = [["problem","Problem addressed"],["scope","Scope and mathematical approach"],["assumptions","Assumptions"],["predictions","Results and predictions"],["evidence","Evidence in the cited work"],["limitations","Limitations"],["questions","Questions to investigate"]];
  const state = { search:"", category:"", kind:"", status:"", era:"", sourcedOnly:false, evidence:"", selected:null, selectedTree:0, view:"explore", returnView:"explore" };
  const formulaState = { search:"", category:"", theory:"", type:"", review:"" };
  const timelineState = { layer:"all", eventType:"" };
  const questionState = { search:"", disposition:"", category:"" };
  const evidenceState = { search:"", type:"", problem:"" };
  const categoryColors = new Map([
    ["Historical foundations","#f59e0b"],["Formulations","#60a5fa"],["Foundations & interpretations","#c084fc"],
    ["Quantum field theory","#34d399"],["Quantum information & open systems","#22d3ee"],["Quantum gravity & spacetime","#f472b6"],
    ["Quantum cosmology","#fb7185"],["Beyond standard quantum theory","#facc15"],["Mathematical structures","#a3e635"],
    ["Quantum optics & AMO","#f0abfc"],["Quantum many-body & condensed matter","#2dd4bf"],["Quantum chemistry & electronic structure","#a7f3d0"],["Astroparticle physics & cosmology","#818cf8"],["Nuclear quantum theory","#fb923c"]
  ]);
  const relationLabels = {
    precursor:"precursor of",reformulates:"reformulates",extends:"extends","challenged by":"challenges / challenged by",
    interprets:"interprets",unifies:"feeds into / unifies",supports:"supports",generalizes:"generalizes",overlaps:"overlaps",motivates:"motivates",formalizes:"formalizes",challenges:"challenges"
  };
  const $ = s => document.querySelector(s);
  const $$ = s => [...document.querySelectorAll(s)];
  const esc = v => String(v ?? "").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));

  function filtered(){
    const q = state.search.trim().toLowerCase();
    return theories.filter(t =>
      (!q || [t.name,t.summary,t.core,...t.tags,...t.aliases].join(" ").toLowerCase().includes(q)) &&
      (!state.category || t.category===state.category) &&
      (!state.kind || t.kind===state.kind) &&
      (!state.status || t.status===state.status) &&
      (!state.era || t.era===state.era) &&
      (!state.sourcedOnly || t.provenance!=="catalogued")
    );
  }

  function setOptions(sel, values){
    const el=$(sel), first=el.firstElementChild.outerHTML;
    el.innerHTML=first+values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join("");
  }
  setOptions("#categoryFilter",[...new Set(theories.map(t=>t.category))].sort());
  setOptions("#kindFilter",[...new Set(theories.map(t=>t.kind))].sort());
  setOptions("#statusFilter",[...new Set(theories.map(t=>t.status))].sort());
  setOptions("#eraFilter",[...new Set(theories.map(t=>t.era))]);
  setOptions("#formulaCategory",[...new Set(formulas.map(f=>f.category))].sort());
  setOptions("#formulaType",[...new Set(formulas.map(f=>f.formulaType))].sort());
  const formulaTheoryIds=[...new Set(formulas.flatMap(f=>f.theoryIds))].filter(id=>byId.has(id)).sort((a,b)=>byId.get(a).name.localeCompare(byId.get(b).name));
  const formulaTheorySelect=$("#formulaTheory");
  formulaTheorySelect.innerHTML=formulaTheorySelect.firstElementChild.outerHTML+formulaTheoryIds.map(id=>`<option value="${id}">${esc(byId.get(id).name)}</option>`).join("");
  setOptions("#timelineEventType",[...new Set(developments.map(event=>event.eventType))].sort());
  setOptions("#questionDisposition",questionDispositions);
  setOptions("#questionCategory",[...new Set(questions.map(q=>q.category).filter(Boolean))].sort());
  setOptions("#evidenceType",[...new Set(evidenceRecords.map(item=>item.type))].sort());
  const evidenceProblemSelect=$("#evidenceProblem");
  evidenceProblemSelect.innerHTML=evidenceProblemSelect.firstElementChild.outerHTML+problems.map(problem=>`<option value="${esc(problem.id)}">${esc(problem.name)}</option>`).join("");

  function renderStats(){
    const cat=new Set(theories.map(t=>t.category)).size;
    const sourced=theories.filter(t=>t.provenance!=="catalogued").length;
    $("#stats").innerHTML=[
      [theories.length,"catalogued theories & frameworks"],
      [cat,"major categories"],
      [relations.length,"typed connections"],
      [formulas.length,"formula atlas entries"],
      [developments.length,"reviewed development events"],
      [questions.length,"structured research questions"],
      [problems.length,"scientific problems"],
      [evidenceRecords.length,"evidence & constraint records"],
      [passports.length,"curated Theory Passports"],
      [`${sourced}/${theories.length}`,"entries with review/source provenance"]
    ].map(([n,l])=>`<div class="stat"><strong>${n}</strong><span>${l}</span></div>`).join("");
  }

  function renderLegend(){
    $("#legend").innerHTML=[...categoryColors].map(([name,color])=>`<span class="legend-item"><i class="dot" style="background:${color}"></i>${esc(name)}</span>`).join("");
  }

  function related(id){
    return relations.filter(r=>evidenceMatches(r)&&(r.from===id||r.to===id)).map(r=>{
      const outbound=r.from===id, other=byId.get(outbound?r.to:r.from);
      return {r,other,outbound};
    }).filter(x=>x.other);
  }

  function evidenceMatches(r){return !state.evidence || (state.evidence==='sourced'?r.sourceIds.length>0:r.evidenceType===state.evidence);}
  function viewHash(view){
    const params=new URLSearchParams();
    if(['map','catalog','timeline'].includes(view))for(const key of ['search','category','kind','status','era'])if(state[key])params.set(key,state[key]);
    if(['map','catalog','timeline'].includes(view)&&state.sourcedOnly)params.set('sourced','1');
    if(view==='timeline'){
      if(timelineState.layer!=='all')params.set('layer',timelineState.layer);
      if(timelineState.eventType)params.set('eventType',timelineState.eventType);
    }
    if(['map','lineage'].includes(view)&&state.evidence)params.set('evidence',state.evidence);
    if(view==='lineage'){params.set('tree',trees[state.selectedTree].name);if(state.selected)params.set('theory',state.selected);}
    if(view==='formula'){for(const key of ['search','category','theory','type','review'])if(formulaState[key])params.set(key,formulaState[key]);const back=safeReturn(new URLSearchParams(location.hash.split('?').slice(1).join('?')).get('returnTo'));if(back)params.set('returnTo',back);}
    return '#/'+view+(params.size?'?'+params:'');
  }
  function rememberFilters(){history.replaceState(null,'',viewHash(state.view));}
  function renderCoverage(){
    const count=fn=>theories.filter(fn).length;
    const gaps=new Set(formulaAudit.filter(a=>a.classification==='formula-bearing-gap').map(a=>a.theoryId));
    const rows=[...categoryColors.keys()].map(category=>`<tr><th scope="row">${esc(category)}</th><td>${count(t=>t.category===category)}</td><td>${count(t=>t.category===category&&gaps.has(t.id))}</td><td>${count(t=>t.category===category&&profiles[t.id])}</td></tr>`).join('');
    $('#coverageContent').innerHTML=`<h3>Coverage and review status</h3><p>The census is open. Source attachment does not establish that every claim is verified or experimentally confirmed.</p><p>${theories.length} entries · ${sources.length} bibliography records · ${Object.keys(profiles).length} reading profiles · ${learningPaths.length} learning paths.</p><p>${relations.filter(r=>r.sourceIds.length).length} source-backed relationships; ${relations.filter(r=>!r.sourceIds.length).length} editorial relationships.</p><p>${formulas.length} formulas; ${formulas.filter(f=>f.metadataReview==='explicit').length} explicitly reviewed metadata records. Baseline records still need equation-level review.</p><p>${developments.length} reviewed DevelopmentEvents extend the historical timeline through ${developments.length?Math.max(...developments.map(event=>event.year)):"—"} without changing entity origin dates.</p><div class="comparison-scroll" role="region" aria-label="Coverage by category" tabindex="0"><table class="comparison-table"><caption>Current runtime coverage by category</caption><thead><tr><th scope="col">Category</th><th scope="col">Entries</th><th scope="col">Formula gaps</th><th scope="col">Reading profiles</th></tr></thead><tbody>${rows}</tbody></table></div><p>Formula gaps mean no representative expression has yet been curated. They do not mean the framework lacks mathematics. A linked formula does not establish complete mathematical coverage.</p><p><a href="https://github.com/JeremyHennessy/Quantum-index/blob/main/docs/COVERAGE.md">Coverage methodology and research backlog</a></p>`;
  }
  function safeReturn(value){return typeof value==="string" && value.length<4096 && /^#\/(?:theory\/[a-z0-9-]+|explore|map|timeline|catalog|lineage|formula|compare|problems|evidence|questions|learn|workspace|coverage)(?:\?|$)/.test(value)?value:"";}
  function theoryLink(id,from=state.returnView){
    const params=new URLSearchParams({from});
    if(from==="learn"&&learningPathId)params.set("path",learningPathId);
    if(from==="compare")params.set("compare",compareIds.join(","));
    if(from==="problems")params.set("returnTo",problemHash(selectedProblemId));
    if(from==="evidence")params.set("returnTo",evidenceHash());
    if(from==="formula")params.set("returnTo",location.hash.startsWith("#/theory/") ? safeReturn(new URLSearchParams(location.hash.split("?")[1]||"").get("returnTo")) || "#/formula" : location.hash);
    if(['catalog','timeline','map','lineage'].includes(from))params.set('returnTo',state.view==='theory'?safeReturn(new URLSearchParams(location.hash.split('?').slice(1).join('?')).get('returnTo'))||viewHash(from):viewHash(from));
    if(state.evidence)params.set('evidence',state.evidence);
    return `#/theory/${encodeURIComponent(id)}?${params}`;
  }
  function formulaLink(id){return `#/formula?theory=${encodeURIComponent(id)}&returnTo=${encodeURIComponent(location.hash)}`;}
  function selectTheory(id, switchLineage=false){
    const t=byId.get(id); if(!t)return;
    state.selected=id;
    renderDetail();
    renderLineage();
    d3.selectAll(".node").classed("selected",d=>d.id===id);
    d3.selectAll(".tree-graph-node").classed("selected",d=>d.id===id);
    const from=state.view==="theory"?state.returnView:state.view;
    navigate(switchLineage ? `#/lineage?theory=${encodeURIComponent(id)}` : theoryLink(id,from));
  }

  function renderTheoryPassport(id){
    const passport=passportByTheory.get(id);
    if(!passport)return "";
    const formulaRecords=passport.formulaIds.map(fid=>formulas.find(f=>f.id===fid)).filter(Boolean);
    const evidence=passport.evidenceIds.map(eid=>evidenceRecords.find(item=>item.id===eid)).filter(Boolean);
    const qs=passport.questionIds.map(qid=>questions.find(item=>item.id===qid)).filter(Boolean);
    const devs=passport.developmentIds.map(did=>developments.find(item=>item.id===did)).filter(Boolean);
    return `<section class="detail-section passport">
      <div class="passport-head"><div><p class="eyebrow">THEORY PASSPORT</p><h4>Research orientation</h4></div><span class="badge">reviewed ${esc(passport.reviewedAt||window.QI_PASSPORTS.reviewedAt)}</span></div>
      <div class="passport-problems">${passport.problemIds.map(pid=>{const p=problemById.get(pid);return p?`<a class="problem-chip" href="${problemHash(pid)}">${esc(p.name)}</a>`:"";}).join("")}</div>
      <dl class="passport-grid">
        <div><dt>Entity type</dt><dd>${esc(passport.entityType)}</dd></div>
        <div><dt>Scientific status</dt><dd>${esc(passport.scientificStatus)}</dd></div>
        <div class="passport-wide"><dt>Core idea</dt><dd>${esc(passport.coreIdea)}</dd></div>
        <div class="passport-wide"><dt>Fundamental objects / degrees of freedom</dt><dd>${esc(passport.degreesOfFreedom)}</dd></div>
        <div class="passport-wide"><dt>Mathematical structure</dt><dd>${esc(passport.mathematicalStructure)}</dd></div>
        <div><dt>Regime / limits</dt><dd>${esc(passport.regime)}</dd></div>
        <div><dt>Evidence / constraints</dt><dd>${esc(passport.evidenceSummary)}</dd></div>
      </dl>
      <details class="passport-details"><summary>Assumptions, consequences and limitations</summary>
        <div class="passport-columns">
          <div><h5>Assumptions</h5><ul>${passport.assumptions.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>
          <div><h5>Predictions / consequences</h5><ul>${passport.predictionsConsequences.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>
          <div><h5>Known limitations</h5><ul>${passport.limitations.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>
        </div>
      </details>
      <div class="passport-links">
        ${formulaRecords.length?`<a class="ghost link-button" href="${formulaLink(id)}">${formulaRecords.length} linked Passport formula${formulaRecords.length===1?"":"s"}</a>`:""}
        ${evidence.map(item=>`<a class="ghost link-button" href="#/evidence?search=${encodeURIComponent(item.title)}">${esc(item.title)}</a>`).join("")}
        ${qs.map(item=>`<a class="ghost link-button" href="#/questions?search=${encodeURIComponent(item.title)}">${esc(item.dispositionLabel)}</a>`).join("")}
      </div>
      ${devs.length?`<div class="passport-developments"><h5>Recent developments</h5>${devs.map(item=>`<p><strong>${esc(item.date)}</strong> · ${esc(item.title)}</p>`).join("")}</div>`:""}
    </section>`;
  }

  function renderDetail(){
    renderDetailPanel($("#detailPanel"));
    renderDetailPanel($("#theoryDetail"));
    bindResearchControls();
  }

  function renderDetailPanel(panel){
    const t=byId.get(state.selected);
    if(!t){panel.innerHTML=$("#emptyDetail").innerHTML;return;}
    const rel=related(t.id);
    const provenance=t.provenance==="primary-sourced"?"Primary sourced":t.provenance==="review-sourced"?"Review sourced":"Catalog seed · source pass pending";
    const linkedSources=(t.sources||[]).map(id=>sourceById.get(id)).filter(Boolean);
    panel.innerHTML=`
      <p class="eyebrow">${esc(t.category)}</p>
      <h3 class="detail-title">${esc(t.name)}</h3>
      ${t.aliases.length?`<div class="aliases">Also: ${t.aliases.map(esc).join(", ")}</div>`:""}
      <div class="badge-row">
        <span class="badge">${esc(t.year)}</span>
        <span class="badge">${esc(t.kind)}</span>
        <span class="badge status-${t.status.includes("established")?"established":t.status.includes("interpretation")?"interpretation":t.status.includes("speculative")?"speculative":""}">${esc(t.status)}</span>
        <span class="badge">${esc(provenance)}</span>
      </div>
      <div class="detail-section"><h4>What it is</h4><p>${esc(t.summary)}</p></div>
      ${(()=>{
        const audit=formulaAuditByTheory.get(t.id);
        if(!audit) return "";
        const linked=audit.formulaIds.map(fid=>formulas.find(f=>f.id===fid)).filter(Boolean);
        return `<div class="detail-section">
          <h4>Formula audit</h4>
          <div class="badge-row">
            <span class="badge">${esc(audit.classification)}</span>
            <span class="badge">${esc(audit.coverageStatus)}</span>
            ${audit.priority!=="not-applicable"?`<span class="badge">${esc(audit.priority)} priority</span>`:""}
          </div>
          ${audit.reviewEvidence?`<p>${esc(audit.reviewEvidence.locator)}</p>${profileCitations(audit.reviewEvidence.sourceIds)}`:""}
          ${linked.length?`<p>${linked.length} source-linked formula${linked.length===1?"":"s"} in the atlas.</p><a class="ghost link-button" href="${formulaLink(t.id)}">View linked formulas</a>`:`<p>${esc(audit.gapReason||"No formula audit reason recorded.")}</p>`}
        </div>`;
      })()}
      <div class="detail-section"><h4>Core idea</h4><p>${esc(t.core)}</p></div>
      ${panel.id==="theoryDetail" ? renderTheoryPassport(t.id)+renderLearningNavigation(t.id)+renderResearchProfile(t.id)+researchControls(t.id) : ""}
      <div class="detail-section"><h4>Concepts</h4><div class="tag-list">${t.tags.map(x=>`<span class="tag">${esc(x)}</span>`).join("")}</div></div>
      <div class="detail-section"><h4>Sources · ${linkedSources.length}</h4>
        ${linkedSources.length ? `<div class="source-list">${linkedSources.map(s=>`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noreferrer"><strong>${esc(s.title)}</strong><span>${esc(s.authors)} · ${esc(s.year)} · ${esc(s.type)}</span></a>`).join("")}</div>` : '<p>Dedicated source pass not completed for this entry yet.</p>'}
        ${t.lastReviewed?`<p class="reviewed">Last source review: ${esc(t.lastReviewed)}</p>`:""}
      </div>
      <div class="detail-section"><h4>Connections · ${rel.length}</h4><div class="relation-list">
        ${rel.slice().sort((a,b)=>a.other.year-b.other.year).map(({r,other,outbound})=>`
          <a class="relation" href="${theoryLink(other.id)}">
            <span class="relation-main"><strong>${esc(other.name)}</strong><em>${esc(r.evidenceType)} · ${esc(r.confidence)}${r.sourceIds.length?` · ${r.sourceIds.length} source${r.sourceIds.length===1?"":"s"}`:" · unsourced editorial"}</em></span>
            <small>${esc(relationLabels[r.type]||r.type)}${outbound?" →":" ←"}</small>
          </a>${r.evidenceNote?`<details class="relation-evidence"><summary>Relationship evidence</summary><p>${esc(r.evidenceNote)}</p>${r.sourceLocator?`<p class="reviewed">${esc(r.sourceLocator)}</p>`:""}${profileCitations(r.sourceIds)}</details>`:""}` ).join("")||'<p>No typed connections yet.</p>'}
      </div></div>
      <div class="detail-section detail-actions"><a class="ghost link-button" href="#/lineage?theory=${encodeURIComponent(t.id)}">Trace thought tree</a><a class="ghost link-button" href="#/theory/${encodeURIComponent(t.id)}">Permanent link</a>${panel.id==="theoryDetail"?comparisonAction(t.id):""}</div>`;
  }

  function researchControls(id){
    const data=window.QI_WORKSPACE.data;
    return `<section class="detail-section research-tools" aria-label="Personal research tools"><h4>My research</h4><div class="detail-actions"><button class="ghost" id="toggleBookmark" aria-pressed="${data.bookmarks.includes(id)}">${data.bookmarks.includes(id)?"Remove bookmark":"Bookmark entry"}</button><button class="ghost" id="toggleRead" aria-pressed="${data.read.includes(id)}">${data.read.includes(id)?"Mark unread":"Mark as read"}</button></div><label for="researchNote">Your notes (saved on this browser)</label><textarea id="researchNote" rows="5" maxlength="20000">${esc(noteDrafts.get(id)?.text??data.notes[id]??"")}</textarea><button class="ghost" id="saveNote">Save note</button><p id="researchStatus" role="status">${esc(window.QI_WORKSPACE.error||(noteDrafts.has(id)?"Unsaved draft restored on this tab.":""))}</p><div id="noteConflict"></div></section>`;
  }
  function bindResearchControls(){
    if(!$("#saveNote"))return;
    const id=state.selected;
    const baseNote=noteDrafts.get(id)?.base??window.QI_WORKSPACE.data.notes[id]??'';
    const settleDraft=(saved,submitted)=>{const latest=noteDrafts.get(id);if(!latest||latest.text===submitted)noteDrafts.delete(id);else noteDrafts.set(id,{text:latest.text,base:saved});persistDrafts();};
    $('#researchNote').oninput=()=>{const text=$('#researchNote').value;if(text===baseNote)noteDrafts.delete(id);else noteDrafts.set(id,{text,base:baseNote});$('#researchStatus').textContent=persistDrafts()?'Unsaved draft retained on this tab. Save note to include it in backups.':'Draft could not be stored. Keep this tab open and copy your text.';};
    for(const [button,key] of [["#toggleBookmark","bookmarks"],["#toggleRead","read"]])$(button).onclick=async()=>{const next=window.QI_WORKSPACE.data;next[key]=next[key].includes(id)?next[key].filter(x=>x!==id):[...next[key],id];const saved=await window.QI_WORKSPACE.saveAsync(next);if(state.selected!==id||state.view!=='theory')return;if(saved){const pressed=window.QI_WORKSPACE.data[key].includes(id);$(button).setAttribute("aria-pressed",String(pressed));$(button).textContent=key==="bookmarks"?(pressed?"Remove bookmark":"Bookmark entry"):(pressed?"Mark unread":"Mark as read");$("#researchStatus").textContent="Saved on this browser.";}else $("#researchStatus").textContent=window.QI_WORKSPACE.error;};
    $("#saveNote").onclick=async()=>{
      const text=$('#researchNote').value;noteDrafts.set(id,{text,base:noteDrafts.get(id)?.base??baseNote});persistDrafts();
      if(await window.QI_WORKSPACE.saveNote(id,text,noteDrafts.get(id).base)){settleDraft(text,text);if(state.selected!==id||state.view!=='theory')return;bindResearchControls();$('#noteConflict').innerHTML='';$('#researchStatus').textContent=noteDrafts.has(id)?'Earlier text saved; your newer draft is still unsaved.':'Note saved on this browser.';}
      else{if(state.selected!==id||state.view!=='theory')return;$('#researchStatus').textContent=window.QI_WORKSPACE.error;
        if(window.QI_WORKSPACE.error.includes('another tab')){
          window.QI_WORKSPACE.refresh();const current=window.QI_WORKSPACE.data.notes[id]||'';
          $('#noteConflict').innerHTML=`<label for="currentSavedNote">Current saved note</label><textarea id="currentSavedNote" readonly rows="5">${esc(current)}</textarea><button class="ghost" id="combineNote">Keep both notes and save</button>`;
          $('#combineNote').onclick=async()=>{const submitted=$('#researchNote').value,combined=current+'\n\n— Draft from this tab —\n'+submitted;if(combined.length>20000){$('#researchStatus').textContent='Combined note exceeds 20,000 characters. Copy both versions and shorten your draft.';return;}if(await window.QI_WORKSPACE.saveNote(id,combined,current)){settleDraft(combined,submitted);if(state.selected!==id||state.view!=='theory')return;renderDetail();$('#researchStatus').textContent=noteDrafts.has(id)?'Both earlier notes saved; your newer draft is still unsaved.':'Both notes saved.';}else if(state.selected===id&&state.view==='theory')$('#researchStatus').textContent=window.QI_WORKSPACE.error;};
        }
      }
    };
  }
  function renderWorkspace(){
    const data=window.QI_WORKSPACE.data;
    $("#workspaceContent").innerHTML=`<article class="card comparison-panel"><div class="eyebrow">PERSONAL WORKSPACE</div><h3>My research</h3><p>Bookmarks, notes and reading progress stay in this browser. They are not synced or backed up automatically. Export a backup before clearing browser data or changing devices.</p><div class="detail-actions"><button class="ghost" id="exportWorkspace">Export backup</button><button class="ghost" id="exportNotebook"${window.QI_WORKSPACE.recoveryNeeded?" disabled":""}>Export research notebook</button><label class="ghost">Choose backup to import <input id="importWorkspace" type="file" accept="application/json,.json"></label></div><p id="workspaceStatus" role="status">${esc(window.QI_WORKSPACE.error)}</p><div id="importPreview"></div><h4>Learning progress</h4>${learningPaths.map(p=>`<section class="workspace-path" data-workspace-path="${p.id}"><h5><a href="${learningHash(p.id)}">${esc(p.title)}</a></h5>${renderPathProgress(p,pathProgress(p,data.read))}</section>`).join("")}<section class="workspace-collections" aria-label="Saved research"><h4>Find saved research</h4><label for="workspaceSearch">Search saved entries, notes and comparisons</label><input id="workspaceSearch" type="search" value="${esc(workspaceSearch)}" placeholder="Name, alias, tag or note text…" aria-describedby="workspaceSearchHelp" /><p id="workspaceSearchHelp" class="muted">Search filters your saved lists below. Learning progress and exports include your whole workspace. The research notebook is a readable Markdown file; use the JSON backup to restore your data.</p><p id="workspaceSearchStatus" role="status"></p><div id="workspaceCollections"></div></section></article>`;
    $("#workspaceSearch").oninput=e=>{workspaceSearch=e.target.value;renderWorkspaceCollections();};
    renderWorkspaceCollections();
    $("#exportNotebook").onclick=()=>{try{const blob=new Blob([window.QI_WORKSPACE.exportMarkdown()],{type:"text/markdown;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="quantum-index-research.md";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$("#workspaceStatus").textContent="Research notebook download requested. Use Export backup for a restorable JSON copy.";}catch(e){$("#workspaceStatus").textContent=e.message;}};
    $("#exportWorkspace").onclick=()=>{const blob=new Blob([window.QI_WORKSPACE.exportText()],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=window.QI_WORKSPACE.recoveryNeeded?"quantum-index-recovery.txt":"quantum-index-research.json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$("#workspaceStatus").textContent="Backup download requested. Keep the downloaded file somewhere safe.";};
    $("#importWorkspace").onchange=async e=>{const file=e.target.files[0];$("#importPreview").innerHTML="";if(!file)return;try{if(file.size>window.QI_WORKSPACE.maxBytes)throw new Error("Backup is too large (maximum 1 MB).");const incoming=window.QI_WORKSPACE.validate(JSON.parse(await file.text()));$("#importPreview").innerHTML=`<p>Import ${incoming.bookmarks.length} bookmarks, ${Object.keys(incoming.notes).length} notes, ${incoming.read.length} read entries and ${incoming.comparisons.length} comparisons. Different notes for the same entry are appended; existing work is retained.</p><button class="ghost" id="confirmImport">Merge this backup</button>`;$("#confirmImport").onclick=async()=>{try{if(await window.QI_WORKSPACE.mergeAsync(incoming)){renderWorkspace();$("#workspaceStatus").textContent="Backup merged and saved on this browser.";}else $("#workspaceStatus").textContent=window.QI_WORKSPACE.error;}catch(e){$("#workspaceStatus").textContent=e.message;}};}catch(e){$("#workspaceStatus").textContent=e.message;}};
  }
  function renderWorkspaceCollections(){
    const data=window.QI_WORKSPACE.data,q=workspaceSearch.trim().toLowerCase();
    const matches=id=>{const t=byId.get(id);return !q||[t.name,...t.aliases,...t.tags,data.notes[id]||""].join(" ").toLowerCase().includes(q);};
    const list=(label,ids,key)=>{const shown=ids.filter(matches);return `<section data-saved-list="${key}"><h4>${label} · ${shown.length} / ${ids.length}</h4><div class="profile-collection">${shown.map(id=>`<a class="source-link" href="${theoryLink(id,"workspace")}"><strong>${esc(byId.get(id).name)}</strong>${data.notes[id]?`<span>${esc(data.notes[id].slice(0,180))}</span>`:""}</a>`).join("")||`<p class="muted">${ids.length?"No matches. Try another search or clear the search field.":"Nothing saved in this list yet."}</p>`}</div></section>`;};
