    const read=window.QI_WORKSPACE.data.read;
    $("#learningPaths").innerHTML=`<div class="card comparison-panel"><div class="eyebrow">GUIDED READING</div><h3>Choose a question to explore</h3><p>Follow a suggested reading order, inspect the cited sources, then compare the approaches. These are editorial learning routes, not historical chains or claims of experimental confirmation.</p><div class="detail-actions">${learningPaths.map(p=>`<a class="ghost link-button" href="${learningHash(p.id)}"${p===selected?' aria-current="page"':""}>${esc(p.title)}</a>`).join("")}${selected?'<a class="ghost link-button" href="#/learn">All paths</a>':""}</div></div>${shown.map(p=>`<article class="card comparison-panel learning-path" data-learning-path="${p.id}"><h3>${esc(p.title)}</h3><p>${esc(p.goal)}</p><p><strong>Before you start:</strong> ${esc(p.prerequisites)}</p>${renderPrimer(p.primer)}${renderLearningReferences(p)}${renderPathProgress(p,pathProgress(p,read))}<ol class="learning-steps">${p.steps.map(step=>`<li><a href="${learningStepLink(step.theoryId,p.id)}">${esc(byId.get(step.theoryId).name)}</a><span class="learning-step-status${read.includes(step.theoryId)?" is-read":""}">${read.includes(step.theoryId)?"Read":"Not read"}</span><p>${esc(step.why)}</p>${!profiles[step.theoryId]&&passportByTheory.has(step.theoryId)?'<p class="muted">Curated Passport orientation; no separate reading profile yet.</p>':""}</li>`).join("")}</ol><div class="detail-actions"><a class="ghost link-button" href="${comparisonHash(p.comparison)}">Compare key entries</a><a class="ghost link-button" href="${learningHash(p.id)}">Permanent path link</a></div></article>`).join("")}`;
  }
  function renderLearningNavigation(id){
