      ${row("Formula coverage",id=>{const a=formulaAuditByTheory.get(id);return a?.formulaIds.length?`<a href="${formulaLink(id)}">${a.formulaIds.length} linked formulas</a>`:`<p>${esc(a?.gapReason||"Not reviewed")}</p>`;})}
